// Verify the HMAC signature Convex sends (see convex/lib/signing.ts).
// signature = sha256=hex(HMAC(secret, `${timestamp}.${rawBody}`)); reject if older than 5 minutes.
const crypto = require('crypto');
const secret = $env.LENDLOOP_OUTBOUND_SECRET;
const item = $input.first();
const headers = item.json.headers || {};
const ts = headers['x-lendloop-timestamp'];
const sig = headers['x-lendloop-signature'] || '';
const raw = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64').toString('utf8')
  : JSON.stringify(item.json.body);

let valid = false;
if (secret && ts && Math.abs(Date.now() / 1000 - Number(ts)) <= 300) {
  const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${raw}`).digest('hex');
  const a = Buffer.from(expected);
  const b = Buffer.from(sig);
  valid = a.length === b.length && crypto.timingSafeEqual(a, b);
}

// Only pass on the fields the notification needs.
const body = valid ? JSON.parse(raw) : {};
return [{ json: {
  valid,
  eventKey: body.eventKey,
  event: body.event,
  toolName: body.toolName,
  startDate: body.startDate,
  endDate: body.endDate,
  recipientName: body.recipient && body.recipient.name,
  recipientEmail: body.recipient && body.recipient.email,
} }];

// Mock notification: logged to the execution, no real email is sent.
// Swap this node for Send Email / Slack / Discord in production.
const subjects = {
  'loan.requested': (j) => `New request to borrow your ${j.toolName}`,
  'loan.approved': (j) => `Your request for ${j.toolName} was approved`,
  'loan.declined': (j) => `Your request for ${j.toolName} was declined`,
  'loan.returned': (j) => `Thanks for returning ${j.toolName}`,
};
return $input.all().map((item) => {
  const j = item.json;
  const subject = (subjects[j.event] || (() => `LendLoop update about ${j.toolName}`))(j);
  const message = `Hi ${j.recipientName}, ${subject} (${j.startDate} to ${j.endDate}).`;
  console.log(`[LendLoop mock notification] to=${j.recipientEmail} subject="${subject}"`);
  return { json: { eventKey: j.eventKey, to: j.recipientEmail, subject, message, notifiedAt: new Date().toISOString() } };
});
